//! Built-in providers and their model catalogs.
//!
//! The catalogs in `crates/zp-ai/catalog/` are generated by `scripts/update_catalog.py`.

use std::sync::Arc;

use crate::model::{Api, Model};
use crate::oauth::builtin_flow;
use crate::provider::{HttpProvider, Provider};

struct BuiltinProvider {
    id: &'static str,
    name: &'static str,
    env_vars: &'static [&'static str],
    default_model: &'static str,
    /// Main endpoint, used for model listing and models the catalog lacks.
    api: Api,
    base_url: &'static str,
    /// Matching provider on models.dev.
    models_dev_id: Option<&'static str>,
    /// Whether the endpoint lists models (`/models`).
    lists_models: bool,
    /// Signing in is supported (see [`crate::oauth::builtin_flow`]).
    oauth: bool,
    /// API keys are accepted (`false`: signing in only).
    api_key: bool,
    catalog: &'static str,
}

/// An API-key provider listed on models.dev.
#[allow(clippy::too_many_arguments)]
const fn keyed(
    id: &'static str,
    name: &'static str,
    env_vars: &'static [&'static str],
    default_model: &'static str,
    api: Api,
    base_url: &'static str,
    models_dev_id: &'static str,
    catalog: &'static str,
) -> BuiltinProvider {
    BuiltinProvider {
        id,
        name,
        env_vars,
        default_model,
        api,
        base_url,
        models_dev_id: Some(models_dev_id),
        lists_models: true,
        oauth: false,
        api_key: true,
        catalog,
    }
}

